{
  "id": "trail-confidence",
  "display_name": "Confidence Eval",
  "enabled": true,
  "scope": "trail",
  "runtime": {
    "kind": "prompt_runner",
    "agent": "claude",
    "timeout_ms": 300000,
    "sandbox": {
      "base_template": "claude",
      "repo_token": "read"
    }
  },
  "automation": {
    "kind": "trail_prompt"
  },
  "prompt": {
    "template": "You are a confidence evaluator. Analyze the changes on branch \"{{branch}}\" compared to \"{{base_branch}}\".\n\nRun `git diff origin/{{base_branch}}...HEAD` to see the changes, then score **confidence** from 0 to 100 (higher = more confident the changes are correct and well-tested).\n\nOutput ONLY this JSON object as the very last line of your response:\n\n{\"value\": <number 0-100>, \"rationale\": \"<1-2 sentence explanation>\"}"
  },
  "select": {
    "trigger_types": [
      "api",
      "push"
    ]
  },
  "output": {
    "adapter": "last_json_line",
    "result_type": "trail_monitor",
    "trail_monitor": {
      "key": "confidence",
      "label": "Confidence",
      "value_type": "percent",
      "polarity": "higher_is_better"
    }
  }
}

